{% block title %}My bookings{% endblock %}
{% block content %}
<h1 class="title">My bookings</h1>
<nav class="calendar-nav" aria-label="Calendar">
  <div class="calendar-views">
    <a class="button button-secondary" href="{{ day_url }}"{% if view == "day" %} aria-current="page"{% endif %}>Day</a>
    <a class="button button-secondary" href="{{ week_url }}"{% if view == "week" %} aria-current="page"{% endif %}>Week</a>
  </div>
  <div class="calendar-steps">
    <a class="button button-secondary" href="{{ previous_url }}" aria-label="{{ previous_label }}">&larr;<span class="step-label"> Previous</span></a>
    <a class="button button-secondary" href="{{ today_url }}">Today</a>
    <a class="button button-secondary" href="{{ next_url }}" aria-label="{{ next_label }}"><span class="step-label">Next </span>&rarr;</a>
  </div>
</nav>

{% set today_day = view == "day" and days[0].is_today %}
<h2 class="subtitle calendar-heading{% if today_day %} is-today{% endif %}"{% if today_day %} aria-current="date"{% endif %}>{{ heading }}</h2>
{% if is_empty %}
<p class="hint">{{ empty_text }}</p>
{% endif %}
{% if view == "week" or not is_empty %}
<div class="calendar calendar-{{ view }}">
  {% for d in days %}
  <section class="calendar-day{% if d.is_today and view == "week" %} is-today{% endif %}"{% if view == "week" %} aria-labelledby="day-{{ d.date.isoformat() }}"{% endif %}>
    {% if view == "week" %}
    <h3 class="calendar-day-heading" id="day-{{ d.date.isoformat() }}"{% if d.is_today %} aria-current="date"{% endif %}>{% if d.is_today %}Today, {% endif %}{{ d.label }}</h3>
    {% endif %}
    {% if d.bookings %}
    <ul class="calendar-bookings">
      {% for b in d.bookings %}
      <li class="calendar-booking">
        <a class="calendar-booking-link{% if b.organiser_id == person.id %} is-organiser{% endif %}" href="/bookings/{{ b.id }}">
          <span class="booking-when">{{ b.start_at|clock }}–{{ b.end_at|clock }}</span>
          <span class="booking-title">{{ b.title }}</span>
          <span class="booking-where">{{ b.room.name }}, {{ b.office_name }}</span>
          <span class="booking-role">{{ "Organiser" if b.organiser_id == person.id else "Attending" }}</span>
        </a>
      </li>
      {% endfor %}
    </ul>
    {% else %}
    <p class="calendar-nothing">Nothing booked</p>
    {% endif %}
  </section>
  {% endfor %}
</div>
{% endif %}
{% endblock %}

"""People rules: who is active, finding people by name, and who manages an office.

Must never import `core.identity` (it imports this module).
"""

from dataclasses import dataclass

from sqlalchemy import Row
from sqlalchemy.orm import Session

from roombooker.people import store

SEARCH_LIMIT = 20


@dataclass(frozen=True)
class Person:
    id: int
    email: str
    name: str
    home_office_id: int
    home_office_name: str
    is_office_manager: bool


def _to_person(row: Row) -> Person:
    return Person(
        id=row.id,
        email=row.email,
        name=row.name,
        home_office_id=row.home_office_id,
        home_office_name=row.home_office_name,
        is_office_manager=row.is_office_manager,
    )


def search_active_people(session: Session, text: str) -> list[Person]:
    """Active people whose name contains `text` (case-insensitive), sorted by name, at most 20.

    Blank text matches no one.
    """
    text = text.strip()
    if not text:
        return []
    return [_to_person(row) for row in store.search_active(session, text, SEARCH_LIMIT)]


def can_manage_office(person: Person, office_id: int) -> bool:
    """RULE-4 (AD-7): only an office manager of their own home office manages it.

    The one predicate for services and templates alike.
    """
    return person.is_office_manager and person.home_office_id == office_id


def get_active_person(session: Session, person_id: int) -> Person | None:
    """The person with this id, or None when unknown or inactive."""
    row = store.get_person(session, person_id)
    if row is None or not row.active:
        return None
    return _to_person(row)


def active_people_by_email(session: Session) -> dict[str, Person]:
    """{email: person} for everyone active (emails are stored lower-cased)."""
    return {row.email: _to_person(row) for row in store.all_active(session)}


def names(session: Session, person_ids) -> dict[int, str]:
    """{id: name} for these people, including inactive ones (who keep their bookings)."""
    return store.names(session, person_ids)


def office_names(session: Session) -> dict[int, str]:
    """{office id: office name}."""
    return store.office_names(session)

"""Tables and queries for `offices` and `people`.

Imported only by `people.service` and the seed CLI (AD-1). The tables are created
by Alembic (AD-10); these definitions describe them for queries.
"""

from collections.abc import Iterable, Sequence
from dataclasses import dataclass

from sqlalchemy import (
    Boolean,
    Column,
    ForeignKey,
    Integer,
    MetaData,
    Row,
    String,
    Table,
    insert,
    select,
    update,
)
from sqlalchemy.orm import Session

metadata = MetaData()

offices = Table(
    "offices",
    metadata,
    Column("id", Integer, primary_key=True),
    Column("name", String, nullable=False, unique=True),
)

people = Table(
    "people",
    metadata,
    Column("id", Integer, primary_key=True),
    Column("email", String, nullable=False, unique=True),
    Column("name", String, nullable=False),
    Column("home_office_id", Integer, ForeignKey("offices.id"), nullable=False),
    Column("is_office_manager", Boolean, nullable=False, default=False),
    Column("active", Boolean, nullable=False, default=True),
)

_person_columns = (
    people.c.id,
    people.c.email,
    people.c.name,
    people.c.home_office_id,
    offices.c.name.label("home_office_name"),
    people.c.is_office_manager,
    people.c.active,
)


def _person_select():
    return select(*_person_columns).join(offices, people.c.home_office_id == offices.c.id)


def search_active(session: Session, text: str, limit: int) -> Sequence[Row]:
    """Active people whose name contains `text`, ignoring case, sorted by name.

    Matched and sorted in Python with `casefold()`, because SQLite's `lower()` folds
    only ASCII (a few hundred rows, so this is cheap).
    """
    needle = text.casefold()
    rows = session.execute(_person_select().where(people.c.active.is_(True))).all()
    matches = [row for row in rows if needle in row.name.casefold()]
    matches.sort(key=lambda row: (row.name.casefold(), row.id))
    return matches[:limit]


def all_active(session: Session) -> Sequence[Row]:
    return session.execute(_person_select().where(people.c.active.is_(True))).all()


def get_person(session: Session, person_id: int) -> Row | None:
    return session.execute(_person_select().where(people.c.id == person_id)).first()


def names(session: Session, person_ids: Iterable[int]) -> dict[int, str]:
    """Names of these people, active or not."""
    ids = set(person_ids)
    if not ids:
        return {}
    rows = session.execute(select(people.c.id, people.c.name).where(people.c.id.in_(ids)))
    return {row.id: row.name for row in rows}


def office_names(session: Session) -> dict[int, str]:
    return {row.id: row.name for row in session.execute(select(offices.c.id, offices.c.name))}


# --- writes, used only by the seed CLI (AD-3, AD-9) ---------------------------


@dataclass(frozen=True)
class PersonRecord:
    email: str
    name: str
    office: str
    is_office_manager: bool


@dataclass(frozen=True)
class LoadResult:
    offices_created: int
    offices_total: int
    added: int
    updated: int
    reactivated: int
    deactivated_ids: tuple[int, ...]


def ensure_offices(session: Session, names: Iterable[str]) -> tuple[dict[str, int], int]:
    """Create any missing offices by name. Returns name -> id and how many were created."""
    existing = {name: id_ for id_, name in session.execute(select(offices.c.id, offices.c.name))}
    created = 0
    for name in sorted(set(names) - existing.keys()):
        existing[name] = session.execute(insert(offices).values(name=name)).inserted_primary_key[0]
        created += 1
    return existing, created


def load_people(session: Session, records: Sequence[PersonRecord]) -> LoadResult:
    """Upsert people keyed on email; mark anyone missing inactive. Never deletes."""
    office_ids, offices_created = ensure_offices(session, (r.office for r in records))
    current = {
        row.email: row
        for row in session.execute(select(people.c.id, people.c.email, people.c.active))
    }
    added = updated = reactivated = 0
    for record in records:
        values = {
            "name": record.name,
            "home_office_id": office_ids[record.office],
            "is_office_manager": record.is_office_manager,
            "active": True,
        }
        row = current.get(record.email)
        if row is None:
            session.execute(insert(people).values(email=record.email, **values))
            added += 1
        else:
            session.execute(update(people).where(people.c.id == row.id).values(**values))
            updated += 1
            if not row.active:
                reactivated += 1

    seen = {r.email for r in records}
    deactivated = tuple(
        sorted(row.id for email, row in current.items() if row.active and email not in seen)
    )
    if deactivated:
        session.execute(update(people).where(people.c.id.in_(deactivated)).values(active=False))

    return LoadResult(
        offices_created=offices_created,
        offices_total=len(office_ids),
        added=added,
        updated=updated,
        reactivated=reactivated,
        deactivated_ids=deactivated,
    )

"""SQLite engine and session (AD-11 pragmas on every connection)."""

from collections.abc import Iterator
from functools import lru_cache
from pathlib import Path

from sqlalchemy import Engine, create_engine, event
from sqlalchemy.orm import Session

from roombooker.core.settings import get_settings

PRAGMAS = (
    "PRAGMA journal_mode=WAL",
    "PRAGMA busy_timeout=5000",
    "PRAGMA foreign_keys=ON",
)


def _apply_pragmas(dbapi_connection, _connection_record) -> None:
    cursor = dbapi_connection.cursor()
    try:
        for pragma in PRAGMAS:
            cursor.execute(pragma)
    finally:
        cursor.close()


def make_engine(db_path: Path) -> Engine:
    """Create an engine for `db_path`, creating its parent folder if needed."""
    db_path.parent.mkdir(parents=True, exist_ok=True)
    engine = create_engine(f"sqlite:///{db_path}")
    event.listen(engine, "connect", _apply_pragmas)
    return engine


@lru_cache
def _engine_for(db_path: Path) -> Engine:
    return make_engine(db_path)


def get_engine() -> Engine:
    """The shared engine for the configured database path."""
    return _engine_for(get_settings().db_path)


def get_session() -> Iterator[Session]:
    """FastAPI dependency: one session per request."""
    with Session(get_engine(), expire_on_commit=False) as session:
        yield session

"""The only place that converts between UTC and UK time (AD-5).

Services work in aware UTC datetimes; the database holds UTC text
`YYYY-MM-DDTHH:MM:00Z`; the web layer turns UK dates and clock times into UTC with
`uk_to_utc` and back for display with the Jinja filters `clock` and `day`.
"""

from datetime import UTC, date, datetime, time, timedelta
from zoneinfo import ZoneInfo

UK = ZoneInfo("Europe/London")
UTC_FORMAT = "%Y-%m-%dT%H:%M:00Z"


def utc_now() -> datetime:
    """Now, in UTC. Tests replace this to fix the clock."""
    return datetime.now(UTC)


def to_text(moment: datetime) -> str:
    return moment.astimezone(UTC).strftime(UTC_FORMAT)


def ical_utc(moment: datetime) -> str:
    """`20261117T100000Z`: an iCalendar UTC date-time (RFC 5545 form 2)."""
    return moment.astimezone(UTC).strftime("%Y%m%dT%H%M%SZ")


def from_text(text: str) -> datetime:
    return datetime.strptime(text, UTC_FORMAT).replace(tzinfo=UTC)


def uk_now() -> datetime:
    return utc_now().astimezone(UK)


def parse_date(text: str) -> date | None:
    try:
        return date.fromisoformat(text.strip())
    except ValueError:
        return None


def parse_clock(text: str) -> time | None:
    text = text.strip()
    if len(text) != 5 or text[2] != ":":
        return None
    try:
        return time.fromisoformat(text)
    except ValueError:
        return None


def uk_to_utc(day: date, clock: time) -> datetime | None:
    """The UTC moment of a UK date and clock time, or None when the clocks skip it.

    In the autumn hour that happens twice, the first (summer time) one is meant.
    """
    local = datetime.combine(day, clock).replace(tzinfo=UK, fold=0)
    moment = local.astimezone(UTC)
    if moment.astimezone(UK).replace(tzinfo=None) != local.replace(tzinfo=None):
        return None
    return moment


def utc_to_uk(moment: datetime) -> tuple[date, str]:
    """The UK date and `HH:MM` clock time of a UTC moment; the inverse of `uk_to_utc`."""
    local = moment.astimezone(UK)
    return local.date(), local.strftime("%H:%M")


def uk_midnight(day: date) -> datetime:
    """The UTC moment a UK day starts. UK clocks change at 01:00 or 02:00, so midnight
    always exists and happens once."""
    return datetime.combine(day, time()).replace(tzinfo=UK).astimezone(UTC)


def week_start(day: date) -> date:
    """The Monday of `day`'s week."""
    return day - timedelta(days=day.weekday())


def next_quarter_hour(moment: datetime) -> datetime:
    """`moment` rounded up to a quarter hour (unchanged when it is on one)."""
    moment = moment.replace(second=0, microsecond=0) + (
        timedelta(minutes=1) if moment.second or moment.microsecond else timedelta()
    )
    return moment + timedelta(minutes=-moment.minute % 15)


def clock(moment: datetime) -> str:
    """`14:00`, in UK time."""
    return moment.astimezone(UK).strftime("%H:%M")


def day(moment: datetime) -> str:
    """`Tue 17 Nov`, in UK time."""
    local = moment.astimezone(UK)
    return f"{local:%a} {local.day} {local:%b}"


def length_label(minutes: int) -> str:
    """`15 min`, `1 h`, `1 h 45 min`."""
    hours, rest = divmod(minutes, 60)
    parts = ([f"{hours} h"] if hours else []) + ([f"{rest} min"] if rest else [])
    return " ".join(parts)

"""The only place that reads configuration from the environment."""

import os
from dataclasses import dataclass
from pathlib import Path

DEFAULT_DB_PATH = "var/roombooker.db"
DEFAULT_ENV = "local"


@dataclass(frozen=True)
class Settings:
    db_path: Path
    env: str

    @property
    def is_production(self) -> bool:
        return self.env == "production"

    @property
    def database_url(self) -> str:
        return f"sqlite:///{self.db_path}"


def get_settings() -> Settings:
    """Read settings from `ROOMBOOKER_DB_PATH` and `ROOMBOOKER_ENV`."""
    return Settings(
        db_path=Path(os.environ.get("ROOMBOOKER_DB_PATH") or DEFAULT_DB_PATH),
        env=os.environ.get("ROOMBOOKER_ENV") or DEFAULT_ENV,
    )

